// Normalize + validate the incoming form payload. Field names below assume
// a plain JSON POST body: { name, email, company, message }. If your form
// sends different keys, remap them here.
const b = $input.first().json.body || $input.first().json || {};
const email = String(b.email || '').trim();
if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('missing/invalid email in lead payload - got keys: ' + Object.keys(b).join(','));
}
return [{ json: {
  name: String(b.name || '').trim() || 'unknown',
  email,
  company: String(b.company || '').trim(),
  message: String(b.message || '').trim(),
  received_at: new Date().toISOString(),
} }];

