const lead = $('Validate lead').first().json;
const response = $json;

function getText(resp) {
  if (!resp) return '';
  // OpenAI-compatible shape (served by claude-bridge, not Anthropic's own API).
  return resp.choices?.[0]?.message?.content || '';
}

let status = 'SCORED';
let error = '';
let ai = {};
try {
  const text = getText(response);
  if (!text) throw new Error(response?.error?.message || 'Claude returned no text');
  const cleaned = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  const jsonStart = cleaned.indexOf('{');
  const jsonEnd = cleaned.lastIndexOf('}');
  ai = JSON.parse(cleaned.slice(jsonStart, jsonEnd + 1));
} catch (e) {
  status = 'ERROR';
  error = String(e?.message || e).slice(0, 300);
}

let score = Number(ai.score);
if (!Number.isFinite(score)) score = null;

return [{ json: {
  name: lead.name,
  email: lead.email,
  company: lead.company,
  message: lead.message,
  received_at: lead.received_at,
  status,
  score,
  reason: ai.reason || '',
  suggested_reply: ai.suggested_reply || '',
  error,
} }];
